// Builds tests/fixtures/save_v1_0.2.sav with the Mindustry 3DS 0.2 sources (commit a5cfbaf):
//   git show a5cfbaf:source/<file> for world/sim/units/save, content generated by a5cfbaf's tools.
// The fixture lets the current build check that 0.2 saves stay readable.
#include <cstdio>
#include "game.hpp"
#include "save.hpp"
using namespace mdt;
int main(int argc, char** argv) {
    Game g;
    g.width = 30; g.height = 20;
    g.tiles.assign(600, Tile{});
    for (auto& t : g.tiles) t.floor = B_stone;
    g.tile(3, 3)->ore = B_ore_copper; g.tile(4, 3)->ore = B_ore_copper;
    g.tile(10, 15)->env = B_snow_wall;
    g.spawnPlayer = false; g.waveTimer = true; g.winWave = 10; g.sector = 0;
    int core = g.addBuilding(B_core_shard, 25, 10, TeamSharded, 0);
    g.builds[core].items.add(I_copper, 321); g.builds[core].items.add(I_lead, 45);
    g.addBuilding(B_mechanical_drill, 3, 3, TeamSharded, 0);
    for (int x = 5; x <= 23; x++) g.addBuilding(B_conveyor, x, 3 + 0, TeamSharded, 0);
    g.addBuilding(B_duo, 15, 8, TeamSharded, 0);
    g.addBuilding(B_battery, 12, 12, TeamSharded, 0);
    for (int i = 0; i < 600; i++) g.update(1.f);
    auto data = saveGame(g);
    FILE* f = std::fopen(argc > 1 ? argv[1] : "save_v1_0.2.sav", "wb");
    std::fwrite(data.data(), 1, data.size(), f); std::fclose(f);
    std::printf("%zu bytes, core copper %d\n", data.size(), (int)g.builds[core].items.amount[I_copper]);
}
